examples.template:
MonarchSectionHeader({{title}}, meta: {{meta}}) {
    Button {} label: {
        HStack(spacing: 4) {
            Text({{linkLabel}})
            Image(systemName: "chevron.right").imageScale(.small)
        }
    }
    .buttonStyle(.monarchLink(.subtle))
    .monarchTextStyle(.caption)
}

